class DNode:
    def __init__(self, val=0, prev=None, next=None):
        self.val = val
        self.prev = prev
        self.next = next

def delete_node(node):
    if node is None:
        return None
    if node.prev is not None:
        node.prev.next = node.next
    if node.next is not None:
        node.next.prev = node.prev
    value = node.val
    node.prev = None
    node.next = None
    return value

def link(values):
    head = None
    tail = None
    for v in values:
        node = DNode(v, tail, None)
        if tail is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head

def values_of(head):
    out = []
    while head is not None:
        out.append(head.val)
        head = head.next
    return out

data = link([1, 2, 3])
print(delete_node(data.next), values_of(data))
print(delete_node(None))

